// SameSite cookie-send model + server-side token check.
function cookieSent(sameSite, method, sameOrigin, topLevel) {
  if (sameOrigin) return true;
  if (sameSite === 'Strict') return false;
  if (sameSite === 'None') return true;
  // Lax: only top-level navigations with safe methods carry the cookie
  if (sameSite === 'Lax') return topLevel && method === 'GET';
  return true; // unset behaves Lax-like here
}
function decide(r) {
  const sent = cookieSent(r.sameSite, r.method, r.sameOrigin, r.topLevel);
  // Server requires a valid synchronizer token on every state change.
  if (!sent) return 'BLOCK(no-cookie)';
  if (!r.validToken) return 'BLOCK(bad-token)';
  return 'ALLOW';
}
const reqs = [
  { name: 'cross-site POST form, Lax, no token', sameSite: 'Lax', method: 'POST', sameOrigin: false, topLevel: true, validToken: false },
  { name: 'top-level GET mutate, Lax, no token', sameSite: 'Lax', method: 'GET', sameOrigin: false, topLevel: true, validToken: false },
  { name: 'cross-site POST, None, no token', sameSite: 'None', method: 'POST', sameOrigin: false, topLevel: false, validToken: false },
  { name: 'first-party POST, Lax, valid token', sameSite: 'Lax', method: 'POST', sameOrigin: true, topLevel: false, validToken: true }
];
for (const r of reqs) console.log(r.name + ' => ' + decide(r));
